// DOCB-14608. Pure logic for ContractStartDialog: building the request bodies
// for POST /feature_subscription/<id>/contract-start (preview) and the matching
// PUT (save), and deciding whether Save may be enabled. Kept free of Vue so the
// backend contract is unit-testable:
//  - expected_start_date must be the row's start_date EXACTLY as the list
//    returned it (ISO string or null) — the backend 409s when it drifted;
//  - start_date is "YYYY-MM-DD";
//  - the PUT additionally requires confirmed: true and a reason of 3-500 chars;
//  - org_id is added by AbstractApiService.post/put, never here.

export const REASON_MIN_LENGTH = 3;
export const REASON_MAX_LENGTH = 500;

export interface ContractStartDialogState {
  /** The row's start_date exactly as the list returned it (ISO string or null). */
  expectedStartDate: string | null;
  /** The candidate date currently picked in the dialog, "YYYY-MM-DD". */
  selectedDate: string;
  /** The date the last successful preview ran for, or null if none yet. */
  previewedDate: string | null;
  reason: string;
  confirmed: boolean;
}

export interface ContractStartPreviewBody {
  expected_start_date: string | null;
  start_date: string;
}

export interface ContractStartSaveBody extends ContractStartPreviewBody {
  confirmed: true;
  reason: string;
}

export function buildPreviewBody(
  state: ContractStartDialogState,
): ContractStartPreviewBody {
  return {
    expected_start_date: state.expectedStartDate,
    start_date: state.selectedDate,
  };
}

export function buildSaveBody(
  state: ContractStartDialogState,
): ContractStartSaveBody {
  return {
    ...buildPreviewBody(state),
    confirmed: true,
    reason: state.reason.trim(),
  };
}

export function isReasonValid(reason: string): boolean {
  const trimmed = reason.trim();
  return (
    trimmed.length >= REASON_MIN_LENGTH && trimmed.length <= REASON_MAX_LENGTH
  );
}

/**
 * Save is only allowed after a successful preview for the SAME date (changing
 * the date invalidates the preview), with a valid reason and the confirm
 * checkbox ticked.
 */
export function isSaveEnabled(state: ContractStartDialogState): boolean {
  return (
    state.previewedDate !== null &&
    state.previewedDate === state.selectedDate &&
    isReasonValid(state.reason) &&
    state.confirmed
  );
}

/**
 * Default for the date input: the day part of the row's current start_date, or
 * "" when the row has none.
 */
export function defaultSelectedDate(expectedStartDate: string | null): string {
  return expectedStartDate ? expectedStartDate.slice(0, 10) : '';
}
