<template>
  <q-dialog v-model="show_popup" position="standard" @hide="cleanupOnhide">
    <q-card class="contract-start-dialog">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold text-white">{{
            $t('change_contract_start')
          }}</span>
        </q-toolbar-title>
        <q-btn
          flat
          round
          dense
          icon="close"
          color="white"
          @click="show_popup = false"
        />
      </q-toolbar>

      <q-card-section>
        <div class="text-caption text-grey q-mb-xs">
          {{ $t('contract_start_explanation') }}
        </div>

        <q-input
          v-model="selectedDate"
          :label="$t('contract_start_date')"
          type="date"
          outlined
          dense
          :max="maxDate"
          @update:model-value="onDateChange"
        />

        <div class="row q-mt-sm">
          <f-btn
            appearance="cancel"
            color="primary"
            :disable="busy"
            @click="preview"
          >
            {{ $t('preview_contract_balance') }}
          </f-btn>
        </div>

        <q-banner
          v-if="conflict"
          class="bg-negative text-white q-mt-sm"
          rounded
        >
          {{ conflictMessage }}
        </q-banner>

        <div v-if="previewing" class="text-center q-py-md">
          <q-spinner size="2em" color="primary" />
        </div>

        <template v-else-if="preview">
          <div class="text-subtitle2 q-mt-md">
            {{ $t('contract_balance_preview') }}
          </div>
          <q-markup-table dense flat bordered class="q-mt-xs">
            <thead>
              <tr>
                <th class="text-left">{{ $t('app') }}</th>
                <th class="text-left">{{ $t('contract_period') }}</th>
                <th class="text-right">{{ $t('annual_allowance') }}</th>
                <th class="text-right">{{ $t('consumed') }}</th>
                <th class="text-right">{{ $t('remaining') }}</th>
              </tr>
            </thead>
            <tbody>
              <tr v-for="app in preview.apps" :key="app.app_id">
                <td class="text-left">{{ app.app_name }}</td>
                <template v-if="app.contract_balance.status === 'calculated'">
                  <td class="text-left">
                    {{ app.contract_balance.period_start }} –
                    {{ app.contract_balance.period_end_exclusive }}
                  </td>
                  <td class="text-right">
                    {{ app.contract_balance.annual_allowance }}
                  </td>
                  <td class="text-right">
                    {{ app.contract_balance.consumed }}
                  </td>
                  <td class="text-right">
                    {{ app.contract_balance.remaining }}
                  </td>
                </template>
                <td v-else colspan="4" class="text-center fsm-muted">
                  {{ $t('contract_balance_not_available') }}
                </td>
              </tr>
            </tbody>
          </q-markup-table>
        </template>

        <q-input
          v-model="reason"
          :label="$t('change_reason')"
          type="textarea"
          outlined
          dense
          autogrow
          class="q-mt-md"
          maxlength="500"
          :counter="true"
          :rules="[(v) => reasonRuleOk(v) || $t('change_reason_required')]"
        />

        <q-checkbox
          v-model="confirmed"
          :label="$t('confirm_contract_start_change')"
          class="q-mt-xs"
        />
      </q-card-section>

      <q-card-actions align="stretch" class="q-pa-none">
        <f-btn
          appearance="cancel"
          class="col-6 buttons"
          :disable="busy"
          @click="show_popup = false"
        >
          {{ $t('cancel') }}
        </f-btn>
        <f-btn
          class="col-6 buttons"
          :disable="!saveEnabled || busy"
          @click="save"
        >
          {{ $t('save') }}
        </f-btn>
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useSubscriptionStore } from 'src/store/User/subscription.store';
import { notify } from 'src/components/notifications/notify';
import type { dynamicObj } from 'src/pages/assets';
import {
  buildPreviewBody,
  buildSaveBody,
  isSaveEnabled,
  isReasonValid,
  defaultSelectedDate,
  type ContractStartDialogState,
} from './contractStartDialogHelpers';

interface PreviewApp {
  app_id: string;
  app_name: string;
  contract_balance:
    | { status: 'unavailable' }
    | {
        status: 'calculated';
        period_start: string;
        period_end_exclusive: string;
        annual_allowance: number;
        consumed: number;
        remaining: number;
        as_of: string;
      };
}

interface PreviewResponse {
  id: string;
  org_id: string;
  previous_start_date: string | null;
  start_date: string;
  apps: PreviewApp[];
  saved: boolean;
}

export default defineComponent({
  name: 'ContractStartDialog',
  props: {
    modelValue: { type: Boolean, required: true },
    // The feature subscription whose contract start is being corrected.
    subscription: { type: Object as () => dynamicObj, default: null },
  },
  emits: ['update:modelValue', 'saved'],
  setup() {
    return { subscriptionStore: useSubscriptionStore() };
  },
  data() {
    return {
      selectedDate: '',
      // The row's start_date exactly as the list returned it — sent back
      // verbatim as expected_start_date so the backend can detect drift (409).
      expectedStartDate: null as string | null,
      previewedDate: null as string | null,
      preview: null as PreviewResponse | null,
      reason: '',
      confirmed: false,
      previewing: false,
      saving: false,
      conflict: false,
      conflictMessage: '',
    };
  },
  computed: {
    show_popup: {
      get(): boolean {
        return this.modelValue;
      },
      set(value: boolean) {
        this.$emit('update:modelValue', value);
      },
    },
    busy(): boolean {
      return this.previewing || this.saving;
    },
    maxDate(): string {
      const end = this.subscription?.end_date as string | undefined;
      return end ? end.slice(0, 10) : '';
    },
    dialogState(): ContractStartDialogState {
      return {
        expectedStartDate: this.expectedStartDate,
        selectedDate: this.selectedDate,
        previewedDate: this.previewedDate,
        reason: this.reason,
        confirmed: this.confirmed,
      };
    },
    saveEnabled(): boolean {
      return isSaveEnabled(this.dialogState);
    },
  },
  watch: {
    modelValue(open: boolean) {
      if (open) this.initFromSubscription();
    },
  },
  mounted() {
    if (this.modelValue) this.initFromSubscription();
  },
  methods: {
    reasonRuleOk(value: string): boolean {
      return isReasonValid(value ?? '');
    },
    initFromSubscription() {
      const start =
        (this.subscription?.start_date as string | undefined) ?? null;
      this.expectedStartDate = start;
      this.selectedDate = defaultSelectedDate(start);
      this.previewedDate = null;
      this.preview = null;
      this.reason = '';
      this.confirmed = false;
      this.conflict = false;
      this.conflictMessage = '';
    },
    onDateChange() {
      // Any date change invalidates the previous preview.
      this.previewedDate = null;
      this.preview = null;
      this.conflict = false;
    },
    async preview() {
      const subId = this.subscription?.id as string | undefined;
      if (!subId) return;
      if (!this.selectedDate) {
        notify.error(this.$t('contract_start_date_required') as string);
        return;
      }
      this.previewing = true;
      this.conflict = false;
      try {
        const result = await this.subscriptionStore.previewContractStart(
          subId,
          buildPreviewBody(this.dialogState),
        );
        if (result) {
          this.preview = result as PreviewResponse;
          this.previewedDate = this.selectedDate;
        } else {
          this.detectConflict();
        }
      } finally {
        this.previewing = false;
      }
    },
    async save() {
      const subId = this.subscription?.id as string | undefined;
      if (!subId || !this.saveEnabled) return;
      this.saving = true;
      this.conflict = false;
      try {
        const result = await this.subscriptionStore.saveContractStart(
          subId,
          buildSaveBody(this.dialogState),
        );
        if (result) {
          this.$emit('saved');
          this.show_popup = false;
        } else {
          this.detectConflict();
        }
      } finally {
        this.saving = false;
      }
    },
    detectConflict() {
      // The store already notified the raw backend message. A 409 means the
      // row's start_date moved under us: the preview is void and the expected
      // value must be re-read, so ask for a reload.
      this.conflict = true;
      this.conflictMessage = this.$t('contract_start_conflict') as string;
      this.previewedDate = null;
      this.preview = null;
    },
    cleanupOnhide() {
      this.preview = null;
      this.previewedDate = null;
      this.conflict = false;
    },
  },
});
</script>

<style scoped lang="scss">
.contract-start-dialog {
  min-width: 480px;
  max-width: 720px;
}

.fsm-muted {
  color: var(--dashboard-text-disabled, #9ca3af);
}
</style>
