import { APP_KEY_PLAN_PREFIXES } from 'src/constants';
import type { FeatureSubscription } from 'src/sdk/auth/models/featureSubscription';

export interface AppRegistryEntry {
  displayName: string;
  appKey: string;
  settingType: string;
}

export type SubStatus = 'active' | 'cancelling' | 'expired' | 'none';

export interface AppRow extends AppRegistryEntry {
  subscription: FeatureSubscription | null;
  planName: string | null;
  status: SubStatus;
  startDate: string | null;
  endDate: string | null;
  daysRemaining: number | null;
}

export function matchesApp(
  planKey: string | undefined | null,
  appKey: string,
): boolean {
  if (!planKey) return false;
  const prefixes = APP_KEY_PLAN_PREFIXES[appKey] || [appKey];
  return prefixes.some(
    (p) => planKey === p || planKey.startsWith(p + '_'),
  );
}

/**
 * Pick the "representative" subscription for an app:
 *  1) active subscriptions sort ahead of inactive ones, and
 *  2) within the same active bucket, the one with the latest end_date wins.
 */
export function pickSubscriptionForApp(
  subscriptions: FeatureSubscription[],
  appKey: string,
): FeatureSubscription | null {
  const matches = subscriptions.filter((s) => matchesApp(s.plan_key, appKey));
  if (matches.length === 0) return null;
  const sorted = [...matches].sort((a, b) => {
    const activeSort = (b.is_active ? 1 : 0) - (a.is_active ? 1 : 0);
    if (activeSort !== 0) return activeSort;
    return new Date(b.end_date).getTime() - new Date(a.end_date).getTime();
  });
  return sorted[0] ?? null;
}

/**
 * Status derivation for the management table:
 *  - active:    is_active && auto_renew !== false  (renews on expiry)
 *  - cancelling: is_active && auto_renew === false (active but won't renew)
 *  - expired:   !is_active
 *  - none:      no subscription at all
 */
export function deriveStatus(sub: FeatureSubscription | null): SubStatus {
  if (!sub) return 'none';
  if (sub.is_active && sub.auto_renew !== false) return 'active';
  if (sub.is_active && sub.auto_renew === false) return 'cancelling';
  return 'expired';
}

export function buildAppRow(
  app: AppRegistryEntry,
  subscriptions: FeatureSubscription[],
): AppRow {
  const sub = pickSubscriptionForApp(subscriptions, app.appKey);
  return {
    ...app,
    subscription: sub,
    planName: sub?.plan_name || null,
    status: deriveStatus(sub),
    startDate: sub?.start_date || null,
    endDate: sub?.end_date || null,
    daysRemaining: sub?.days_remaining ?? null,
  };
}
