<template>
  <div class="fsm-container">
    <DocBitsTable
      :rows="appRows"
      :columns="columns"
      row-key="appKey"
      flat-style
      dense
      table-class=""
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        rowActions: true,
        resizable: false,
        pagination: false,
        columnReorder: false,
      }"
      :row-actions="rowActions"
      @row-action="handleRowAction"
    >
      <!-- App Name -->
      <template #body-cell-displayName="{ row }">
        <span class="text-weight-medium">{{ row.displayName }}</span>
      </template>

      <!-- Plan -->
      <template #body-cell-planName="{ row }">
        <span v-if="row.planName">{{ row.planName }}</span>
        <span v-else class="fsm-muted">{{ $t('not_subscribed') }}</span>
      </template>

      <!-- Status Badge -->
      <template #body-cell-status="{ row }">
        <q-chip
          v-if="row.status === 'active'"
          dense
          color="positive"
          text-color="white"
          size="sm"
        >
          {{ $t('active') }}
        </q-chip>
        <q-chip
          v-else-if="row.status === 'cancelling'"
          dense
          color="warning"
          text-color="white"
          size="sm"
        >
          {{ $t('cancelling') }}
        </q-chip>
        <q-chip
          v-else-if="row.status === 'expired'"
          dense
          color="negative"
          text-color="white"
          size="sm"
        >
          {{ $t('expired') }}
        </q-chip>
        <q-chip
          v-else
          dense
          color="grey-3"
          text-color="grey-8"
          size="sm"
        >
          {{ $t('none') }}
        </q-chip>
      </template>

      <!-- Start Date -->
      <template #body-cell-startDate="{ row }">
        <span v-if="row.startDate">{{ formatDate(row.startDate) }}</span>
        <span v-else class="fsm-muted">&mdash;</span>
      </template>

      <!-- End Date -->
      <template #body-cell-endDate="{ row }">
        <span v-if="row.endDate">{{ formatDate(row.endDate) }}</span>
        <span v-else class="fsm-muted">&mdash;</span>
      </template>

      <!-- Days Remaining -->
      <template #body-cell-daysRemaining="{ row }">
        <template v-if="row.daysRemaining !== null">
          {{ row.daysRemaining > 0 ? row.daysRemaining : 0 }}
        </template>
        <span v-else class="fsm-muted">&mdash;</span>
      </template>

    </DocBitsTable>

    <subscription-dialog
      v-model="showDialog"
      :settings="dialogSettings"
      :setting-type="dialogSettingType"
      :app-key="dialogAppKey"
      :on-confirm="handleDialogConfirm"
    />

    <contract-start-dialog
      v-model="showContractStartDialog"
      :subscription="contractStartSubscription"
      @saved="handleDialogConfirm"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import { useSubscriptionStore } from 'src/store/User/subscription.store';
import { notify } from 'src/components/notifications/notify';
import {
  CONSTANTS,
  docnet_setting,
  doc_operator_setting,
  workflow_builder_setting,
  open_search_enabled,
  grouping_dashboard_setting,
  bod_connection_stream_setting,
  db_direct_access_setting,
  supplier_portal_setting,
} from 'src/constants';
import {
  ADVANCED_WORKFLOW_SETTING_NAME,
} from 'src/pages/Settings/Components/Modules/workflowBuilderHelpers';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import SubscriptionDialog from './SubscriptionDialog.vue';
import ContractStartDialog from './ContractStartDialog.vue';
import { isAdmin } from 'src/utils/UserDetails';
import type { FeatureSubscription } from 'src/sdk/auth/models/featureSubscription';
import type { UnifiedTableColumn, RowActionItem } from 'src/components/Table/types/table/unified-table';
import dateUtil from 'src/utils/date';
import {
  buildAppRow,
  type AppRegistryEntry,
  type AppRow,
} from './featureSubscriptionManagementHelpers';

export type { AppRegistryEntry };

const APP_REGISTRY: AppRegistryEntry[] = [
  { displayName: 'AI Workforce', appKey: CONSTANTS.doc_net, settingType: docnet_setting },
  { displayName: 'Operator', appKey: CONSTANTS.doc_operator, settingType: doc_operator_setting },
  { displayName: 'DocFlow', appKey: CONSTANTS.docflow, settingType: workflow_builder_setting },
  { displayName: 'DocFlow Advanced', appKey: CONSTANTS.docflow_advanced, settingType: ADVANCED_WORKFLOW_SETTING_NAME },
  { displayName: 'AI Search', appKey: CONSTANTS.opensearch, settingType: open_search_enabled },
  { displayName: 'AI Warehouse', appKey: CONSTANTS.grouping_dashboard, settingType: grouping_dashboard_setting },
  { displayName: 'BOD Ingestion', appKey: CONSTANTS.bod_connection_stream, settingType: bod_connection_stream_setting },
  { displayName: 'Integration 3rd Party', appKey: CONSTANTS.vertex_tax, settingType: CONSTANTS.vertex_tax_integration_setting },
  { displayName: 'Supplier Portal', appKey: CONSTANTS.supplier_portal, settingType: supplier_portal_setting },
  { displayName: 'SQL BI Connector', appKey: CONSTANTS.sql_bi_connecter, settingType: db_direct_access_setting },
  { displayName: 'DocScan', appKey: CONSTANTS.doc_scan, settingType: CONSTANTS.DOC_SCAN_MODULE_SETTING },
];

function buildColumns(t: (key: string) => string): UnifiedTableColumn[] {
  return [
    { name: 'displayName', label: t('app'), field: 'displayName', align: 'left', sortable: false },
    { name: 'planName', label: t('subscription'), field: 'planName', align: 'left', sortable: false },
    { name: 'status', label: t('status'), field: 'status', align: 'left', sortable: false },
    { name: 'startDate', label: t('start_date'), field: 'startDate', align: 'left', sortable: false },
    { name: 'endDate', label: t('end_date'), field: 'endDate', align: 'left', sortable: false },
    { name: 'daysRemaining', label: t('days_left'), field: 'daysRemaining', align: 'left', sortable: false },
  ];
}

export default defineComponent({
  name: 'FeatureSubscriptionManagement',
  components: { DocBitsTable, SubscriptionDialog, ContractStartDialog },
  mixins: [dateUtil],
  data() {
    return {
      rowActions: [
        {
          key: 'subscribe',
          label: 'subscribe',
          icon: 'add_circle',
          show: (row: any) => row.status === 'none' || row.status === 'expired',
        },
        {
          key: 'manage',
          label: 'manage_subscription',
          icon: 'settings',
          show: (row: any) => row.status === 'active',
        },
        {
          key: 'resume',
          label: 'resume_subscription',
          icon: 'autorenew',
          show: (row: any) => row.status === 'cancelling',
        },
        {
          // DOCB-14608: global admins only (the endpoint 403s everyone else,
          // org admins included), and only on rows that have a subscription.
          key: 'contract_start',
          label: 'change_contract_start',
          icon: 'event',
          show: (row: any) => isAdmin() && !!row.subscription,
        },
      ] as RowActionItem[],
      showDialog: false,
      dialogAppKey: '',
      dialogSettingType: '',
      dialogSettings: {} as Record<string, unknown>,
      showContractStartDialog: false,
      contractStartSubscription: null as Record<string, unknown> | null,
    };
  },
  setup() {
    const subscriptionStore = useSubscriptionStore();
    const { feature_subscriptions } = storeToRefs(subscriptionStore);
    return {
      feature_subscriptions,
      subscriptionStore,
    };
  },
  computed: {
    columns(): UnifiedTableColumn[] {
      return buildColumns(this.$t);
    },
    appRows(): AppRow[] {
      return APP_REGISTRY.map((app) =>
        buildAppRow(app, this.feature_subscriptions as FeatureSubscription[]),
      );
    },
  },
  mounted() {
    this.subscriptionStore.fetchFeatureSubscriptions();
  },
  methods: {
    formatDate(dateString: string): string {
      return this.formatDateAccordingToPreference(dateString, true);
    },
    openSubscribeDialog(row: AppRegistryEntry) {
      this.dialogAppKey = row.appKey;
      this.dialogSettingType = row.settingType;
      this.dialogSettings = {};
      this.showDialog = true;
    },
    handleRowAction(payload: { action: string; rowId: string; row: any }) {
      if (payload.action === 'subscribe' || payload.action === 'manage') {
        this.openSubscribeDialog(payload.row);
        return;
      }
      if (payload.action === 'resume') {
        void this.resumeSubscription(payload.row);
        return;
      }
      if (payload.action === 'contract_start') {
        this.openContractStartDialog(payload.row);
      }
    },
    openContractStartDialog(row: AppRow) {
      if (!row.subscription) {
        notify.error(this.$t('no_subscription'));
        return;
      }
      this.contractStartSubscription = row.subscription as unknown as Record<
        string,
        unknown
      >;
      this.showContractStartDialog = true;
    },
    async resumeSubscription(row: AppRow) {
      const subId = row.subscription?.id;
      if (!subId) {
        notify.error(this.$t('no_subscription'));
        return;
      }
      await this.subscriptionStore.reactivateFeatureSubscription(subId);
    },
    handleDialogConfirm() {
      this.subscriptionStore.fetchFeatureSubscriptions();
    },
  },
});
</script>

<style scoped lang="scss">
.fsm-container {
  position: relative;
  min-height: 100px;
}

.fsm-muted {
  color: var(--dashboard-text-disabled, #9ca3af);
}
</style>
