<template>
  <div class="row">
    <div class="full-width ">
      <f-btn
        icon="event"
        :label="$t('select')"
        color="primary"
      >
        <q-popup-proxy
          @before-show="updateProxy"
          cover
          transition-show="scale"
          transition-hide="scale"
        >
          <q-date v-model="proxyDate" range minimal>
            <div class="row items-center justify-end q-gutter-sm">
              <f-btn
                :label="$t('close')"
                appearance="tertiary"
                v-close-popup
              />
              <f-btn
                label="OK"
                appearance="tertiary"
                @click="save"
                v-close-popup
              />
            </div>
          </q-date>
        </q-popup-proxy>
      </f-btn>
    </div>
  </div>

  <div class="full-width ">
    <q-markup-table
      flat
      class="dashboard-table-style dashboard-table-height back-white"
    >
      <thead>
        <tr class="table-header-text documnetCol relative-position">
          <th>
            {{ $t('Type') }}
            <span class="orderByParentSpan">
              <span
                class="up-arrow orderBy absolute"
                id="type_asc"
                data-name="type"
                data-direction="asc"
                @click="OrderBy"
              ></span>
              <span
                class="down-arrow orderBy absolute"
                id="type_desc"
                data-name="type"
                data-direction="desc"
                @click="OrderBy"
              ></span>
            </span>
          </th>
          <th>
            {{ $t('from') }}
            <span class="orderByParentSpan">
              <span
                class="up-arrow orderBy absolute"
                id="filename_asc"
                data-name="filename"
                data-direction="asc"
                @click="OrderBy"
              ></span>
              <span
                class="down-arrow orderBy absolute"
                id="filename_desc"
                data-name="filename"
                data-direction="desc"
                @click="OrderBy"
              ></span>
            </span>
          </th>
          <th>
            {{ $t('to') }}
            <span class="orderByParentSpan">
              <span
                class="up-arrow orderBy absolute"
                id="pages_asc"
                data-name="pages"
                data-direction="asc"
                @click="OrderBy"
              ></span>
              <span
                class="down-arrow orderBy absolute"
                id="pages_desc"
                data-name="pages"
                data-direction="desc"
                @click="OrderBy"
              ></span>
            </span>
          </th>
          <th>
            {{ 'Tokens ' + $t('used') }}
            <span class="orderByParentSpan">
              <span
                class="up-arrow orderBy absolute"
                id="status_asc"
                data-name="status"
                data-direction="asc"
                @click="OrderBy"
              ></span>
              <span
                class="down-arrow orderBy absolute"
                id="status_desc"
                data-name="status"
                data-direction="desc"
                @click="OrderBy"
              ></span>
            </span>
          </th>
          <th>
            {{ $t('remaining_tokens') }}
            <span class="orderByParentSpan">
              <span
                class="up-arrow orderBy absolute"
                id="remaining_asc"
                data-name="remaining"
                data-direction="asc"
                @click="OrderBy"
              ></span>
              <span
                class="down-arrow orderBy absolute"
                id="remaining_desc"
                data-name="remaining"
                data-direction="desc"
                @click="OrderBy"
              ></span>
            </span>
          </th>
        </tr>
      </thead>

      <tbody>
        <tr v-if="doc2AppUsage.tokens_used != null">
          <th>
            {{ $t('Document') }}
          </th>
          <th>
            {{ formatDateAccordingToPreference(date2.from, true) }}
          </th>
          <th>
            {{ formatDateAccordingToPreference(date2.to, true) }}
          </th>
          <th>
            {{ doc2AppUsage.tokens_used }}
          </th>
          <th>
            {{ document_remaining_tokens }}
          </th>
        </tr>

        <tr v-else>
          <th>
            {{ $t('Document') }}
          </th>
          <th>
            {{ formatDateAccordingToPreference(date2.from, true) }}
          </th>
          <th>
            {{ getCurrentDate() }}
          </th>
          <th>
            {{ doc2AppUsage.tokens_used }}
          </th>
          <th>
            {{ document_remaining_tokens }}
          </th>
        </tr>

        <tr v-if="hasWorkflowsActive()">
          <th>
            {{ $t('Workflow') }}
          </th>
          <th>
            {{ formatDateAccordingToPreference(date2.from, true) }}
          </th>
          <th>
            {{ formatDateAccordingToPreference(date2.to, true) }}
          </th>
          <th>
            {{ docFlowUsage.tokens_used }}
          </th>
          <th>
            {{ docflow_remaining_tokens }}
          </th>
        </tr>

        <tr v-if="hasAdvancedWorkflowActive()">
          <th>
            {{ $t('advanced_workflow') }}
          </th>
          <th>
            {{ formatDateAccordingToPreference(date2.from, true) }}
          </th>
          <th>
            {{ formatDateAccordingToPreference(date2.to, true) }}
          </th>
          <th>
            {{ docFlowAdvancedUsage.tokens_used }}
          </th>
          <th>
            {{ docflow_advanced_remaining_tokens }}
          </th>
        </tr>

        <tr v-if="hasDocNetActive()">
          <th>
            DocNet
          </th>
          <th>
            {{ formatDateAccordingToPreference(date2.from, true) }}
          </th>
          <th>
            {{ formatDateAccordingToPreference(date2.to, true) }}
          </th>
          <th>
            {{ docNetUsage.tokens_used }}
          </th>
          <th>
            {{ docnet_remaining_tokens }}
          </th>
        </tr>
      </tbody>
    </q-markup-table>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { date } from 'quasar';
import { useSettingStore, useSubscriptionStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import dateUtil from 'src/utils/date';
import {
  workflow_builder_setting,
  docnet_setting,
  YYYY_MM,
  CONSTANTS,
} from 'src/constants';
import { ADVANCED_WORKFLOW_SETTING_NAME } from 'src/pages/Settings/Components/Modules/workflowBuilderHelpers';
import helperMixin from 'src/mixins/helperMixin.js';

export default defineComponent({
  el: '#app',
  mixins: [dateUtil, helperMixin],
  setup() {
    const subscription_store = useSubscriptionStore();
    const { getUsage } = subscription_store;
    const { doc2AppUsage, docFlowUsage, docFlowAdvancedUsage, docNetUsage } =
      storeToRefs(subscription_store);
    const { subscriptions } = storeToRefs(subscription_store);
    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    return {
      date2: ref<{ from: string; to: string }>({ from: '', to: '' }),
      // q-date with `range` may emit either {from, to} or a single date string
      proxyDate: ref<string | { from: string; to: string }>({ from: '', to: '' }),
      getUsage,
      doc2AppUsage,
      docFlowUsage,
      docFlowAdvancedUsage,
      docNetUsage,
      button_label: ref('Select'),
      subscriptions,
      timestamp: '',
      user_settings,
      YYYY_MM,
      workflow_builder_setting,
      docnet_setting,
      docflow_remaining_tokens: ref(0),
      docflow_advanced_remaining_tokens: ref(0),
      document_remaining_tokens: ref(0),
      docnet_remaining_tokens: ref(0),
    };
  },
  mounted: function () {
    this.setCurrentMonth();
    this.getRemainingTokens();
  },
  methods: {
    async setCurrentMonth() {
      const timeStamp = Date.now();
      const current_month_year = date.formatDate(timeStamp, this.YYYY_MM); //YYYY-MM-01 valid for both Chrome and Firefox

      const newDate = new Date(current_month_year);
      const startOfMonth = date.formatDate(
        date.startOfDate(newDate, 'month'),
        'YYYY/MM/DD',
      );
      const endOfMonth = date.formatDate(
        date.endOfDate(newDate, 'month'),
        'YYYY/MM/DD',
      );

      const range = { from: startOfMonth, to: endOfMonth };
      this.date2 = range;
      this.proxyDate = range;

      this.showLoading();
      try {
        await this.getUsage({
          start_date: startOfMonth,
          end_date: endOfMonth,
        });
      } finally {
        this.hideLoading();
      }
    },
    async getRemainingTokens() {
      await useSubscriptionStore().getSubscriptionFromServer();
      const subscriptions = useSubscriptionStore().getSubscription();
      if (!Array.isArray(subscriptions)) {
        return;
      }
      const now = new Date();
      const active = subscriptions.filter((subscription) => {
        if (!subscription.end_date) return true;
        return new Date(subscription.end_date) >= now;
      });

      for (const subscription of active) {
        for (const app of subscription.apps ?? []) {
          const pending = parseInt(app.pending_credit ?? '0');
          switch (app.app_key) {
            case CONSTANTS.docflow_advanced:
              this.docflow_advanced_remaining_tokens = pending;
              break;
            case CONSTANTS.docflow:
              this.docflow_remaining_tokens = pending;
              break;
            case CONSTANTS.doc_net:
              this.docnet_remaining_tokens = pending;
              break;
            case CONSTANTS.fellow_doc2:
              this.document_remaining_tokens = pending;
              break;
          }
        }
      }
    },
    updateProxy() {
      this.proxyDate = this.date2;
    },
    getCurrentDate() {
      const current = new Date();
      const current_date = `${current.getDate()}/${current.getMonth() + 1}/${current.getFullYear()}`;
      const formated_current_date = this.formatDateAccordingToPreference(
        current_date,
        true,
      );
      this.timestamp = formated_current_date;
      return this.timestamp;
    },
    async save() {
      // q-date with `range` returns an object {from, to} for ranges
      // and a plain date string when the user taps a single day.
      const picked = this.proxyDate;
      let range: { from: string; to: string };
      if (typeof picked === 'string' && picked) {
        range = { from: picked, to: picked };
      } else if (picked && picked.from && picked.to) {
        range = { from: picked.from, to: picked.to };
      } else {
        return;
      }

      this.date2 = range;
      this.proxyDate = range;
      this.showLoading();
      try {
        await this.getUsage({
          start_date: range.from,
          end_date: range.to,
        });
      } finally {
        this.hideLoading();
      }
    },
    hasWorkflowsActive() {
      return this.user_settings[workflow_builder_setting] ? true : false;
    },
    hasAdvancedWorkflowActive() {
      return this.user_settings[ADVANCED_WORKFLOW_SETTING_NAME] ? true : false;
    },
    hasDocNetActive() {
      if (this.user_settings[docnet_setting]) return true;
      const subs = this.subscriptions;
      if (Array.isArray(subs)) {
        return subs.some(
          (sub) => sub.apps?.some((app) => app.app_key === CONSTANTS.doc_net),
        );
      }
      return false;
    },
  },
});
</script>

<style lang="scss" scoped></style>
